//! Exact OUTPUT for attributes precede its native DOMTokenList binding.
use super::*;
#[test]
fn output_for_domstring_conversion_reentry_replaces_actual_attr_and_keeps_abrupt_effects(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),old=output.getAttributeNode('for'),calls=0;output.setAttribute('for',{toString:function(){calls++;output.removeAttribute('for');output.setAttribute('for','callback');return 'A\ud800z';}});var actual=output.getAttributeNode('for');if(calls!==1||actual===old||old.ownerElement!==null||old.value!=='seed'||actual.value!=='A\ud800z')throw 'conversion uses current actual attribute';var marker={},caught;try{output.setAttribute('for',{toString:function(){output.setAttribute('for','abrupt callback');throw marker;}});}catch(e){caught=e;}if(caught!==marker||output.getAttribute('for')!=='abrupt callback'||output.getAttributeNode('for')!==actual)throw 'abrupt conversion keeps completed author effects';caught=false;try{output.setAttribute('for',Symbol('for'));}catch(e){caught=e instanceof TypeError;}if(!caught||actual.value!=='abrupt callback')throw 'symbol conversion refusal';"#);}
#[test]
fn output_for_domstring_inert_clone_adoption_no_main_slots_and_whole_import_guard(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),source=owner.createElement('output');source.setAttribute('for','A\ud800z B\udfffz');var copy=source.cloneNode(true),a=copy.getAttributeNode('for'),target=document.implementation.createHTMLDocument('target');target.adoptNode(copy);target.body.appendChild(copy);if(copy.getAttribute('for')!==source.getAttribute('for')||a===source.getAttributeNode('for')||copy.ownerDocument!==target||a.ownerDocument!==target)throw 'independent clone and actual adopted attributes';source.setAttribute('for','fresh');if(a.value!=='A\ud800z B\udfffz')throw 'independent copied record';"#);let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());p.begin_job();let error=p.runtime.execute("document.importNode(copy,true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("Import supports ordinary HTML containers"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);let slots=d.nodes.len();p.state.node_limit=slots;p.begin_job();run(&mut d,&mut f,&mut p,r#"var isolated=owner.createElement('output');isolated.setAttribute('for','X\ud800');var attr=isolated.getAttributeNode('for');attr.value='Y\udfff';if(isolated.getAttribute('for')!=='Y\udfff'||attr.ownerDocument!==owner||a.value!=='A\ud800z B\udfffz')throw 'fresh inert exact source without main slots';document.getElementById('output').setAttribute('for','Z\ud800');"#);assert_eq!(d.nodes.len(),slots);}
#[test]
fn output_for_domstring_qualified_foreign_and_other_element_guards_are_atomic(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var output=document.getElementById('output'),other=document.createElement('div'),shape=document.createElementNS('http://www.w3.org/2000/svg','svg');");let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());for source in [r#"output.setAttributeNS('urn:attribute','for','A\ud800');"#,r#"other.setAttribute('for','A\ud800');"#,r#"shape.setAttribute('for','A\ud800');"#]{p.begin_job();assert!(p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err(),"{source}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);}p.begin_job();run(&mut d,&mut f,&mut p,r#"output.setAttribute('for','B\udfff');if(output.getAttribute('for')!=='B\udfff')throw 'fresh exact native write recovery';"#);}
#[test]
fn output_for_domstring_write_limits_preserve_native_records_and_recover(){for source in [r#"output.setAttribute('for','long A\ud800z B\udfffz');"#,r#"output.setAttributeNS(null,'for','long A\ud800z B\udfffz');"#,r#"attr.value='long A\ud800z B\udfffz';"#]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var output=document.getElementById('output'),attr=output.getAttributeNode('for');");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=0,_=>p.state.execution_deadline=Some(Instant::now())};let error=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("work")||error.contains("allowance")||error.contains("limit")||error.contains("bound"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,r#"if(output.getAttributeNode('for')!==attr||attr.value!=='long A\ud800z B\udfffz')throw 'fresh writer identity recovery';"#);}}}
#[test]
fn output_for_domstring_saved_child_origin_precedes_author_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var saved=frame.contentWindow.Function('node','value',"node.setAttribute('for',value);"),calls=0;saved(output,'A\ud800z');"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.set_location(&crate::navigation::address("https://other-output-for.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("saved(output,{toString:function(){calls++;return 'bad';}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.set_location(&crate::navigation::address("https://output-for-units.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,r#"if(calls||output.getAttribute('for')!=='A\ud800z')throw 'origin before conversion';saved(output,'B\udfffz');if(output.getAttribute('for')!=='B\udfffz')throw 'fresh captured origin recovery';"#);}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner><label id=label for=output>Result</label><output id=output for=seed>ready</output><input id=field value=seed></form><div id=mount></div></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://output-for-units.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn output_for_domstring_public_write_exact_css_and_independent_label_association(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),labels=output.labels,label=document.getElementById('label');output.setAttribute('for','A\ud800z B\udfffz A�z');if(output.getAttribute('for')!=='A\ud800z B\udfffz A�z'||output.getAttributeNode('for').value!==output.getAttribute('for')||output.matches('[for="A�z B�z A�z"]'))throw 'exact native output for';if(output.labels!==labels||labels.length!==1||labels[0]!==label||label.control!==output||label.form!==document.getElementById('owner'))throw 'output for does not select its own labels';"#);}
#[test]
fn output_for_domstring_attached_attr_aliases_preserve_identity_and_old_values(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),a=output.getAttributeNode('for'),watch=new MutationObserver(function(){});watch.observe(output,{attributes:true,attributeOldValue:true});a.value='A\ud800z';a.nodeValue='B\udfffz';a.textContent='C\ud800z';var records=watch.takeRecords();if(a!==output.getAttributeNode('for')||a.value!=='C\ud800z'||output.getAttribute('for')!==a.value||records.length!==3||records[0].oldValue!=='seed'||records[1].oldValue!=='A\ud800z'||records[2].oldValue!=='B\udfffz'||records[2].target!==output||records[2].attributeName!=='for'||records[2].attributeNamespace!==null)throw 'actual for Attr identity and observations';"#);}
#[test]
fn output_for_domstring_null_namespace_writes_ignore_foreign_collision_after_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output');output.setAttributeNS('urn:attribute','for','foreign');var foreign=output.getAttributeNodeNS('urn:attribute','for'),a=output.getAttributeNodeNS(null,'for'),calls=0;output.setAttributeNS(null,'for',{toString:function(){calls++;output.setAttributeNS(null,'for','callback');return 'A\ud800z';}});if(calls!==1||output.getAttributeNodeNS(null,'for')!==a||a.value!=='A\ud800z'||foreign!==output.getAttributeNodeNS('urn:attribute','for')||foreign.value!=='foreign'||output.getAttributeNS(null,'for')!=='A\ud800z')throw 'exact converted null namespace output attribute';"#);}
